solution.src/sheetcalc.py:
LIMIT = 9999999
DIVMODE = "floor"
ORDER = "row"
HAS_FUNCS = True
HAS_CMP = False
FN = {"SUM": "TOTAL", "MIN": "MIN", "MAX": "MAX", "AVG": "AVERAGE", "COUNT": "TALLY", "ABS": "ABS"}
AGG = [FN[k] for k in ("SUM", "MIN", "MAX", "AVG", "COUNT") if k in FN]
CANON = {v: k for k, v in FN.items()}
DIG = "0123456789"
ALPHA = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ"
CMPOPS = ("=", "<>", "<", "<=", ">", ">=")


class Err(Exception):
    def __init__(self, code):
        self.code = code


def valid_cell(t):
    return len(t) >= 2 and t[0] in "ABCDEFGHIJ" and all(c in DIG for c in t[1:]) and t[1] != "0" and len(t) <= 3


def tokenize(s):
    toks = []
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c in " \t":
            i += 1
        elif c in DIG:
            j = i
            while j < n and s[j] in DIG:
                j += 1
            toks.append(("int", s[i:j]))
            i = j
        elif c in ALPHA:
            j = i
            while j < n and s[j] in ALPHA:
                j += 1
            k = j
            while k < n and s[k] in DIG:
                k += 1
            toks.append(("ref" if k > j else "name", s[i:k]))
            i = k
        elif HAS_CMP and s[i:i + 2] in ("<>", "<=", ">="):
            toks.append((s[i:i + 2], s[i:i + 2]))
            i += 2
        elif c in "+-*/%(),:" or (HAS_CMP and c in "=<>"):
            toks.append((c, c))
            i += 1
        else:
            raise Err("#SYN")
    return toks


class Parser:
    def __init__(self, toks):
        self.t = toks
        self.i = 0

    def peek(self):
        return self.t[self.i][0] if self.i < len(self.t) else None

    def take(self):
        if self.i >= len(self.t):
            raise Err("#SYN")
        tok = self.t[self.i]
        self.i += 1
        return tok

    def expect(self, k):
        if self.peek() != k:
            raise Err("#SYN")
        self.i += 1

    def expr(self):
        left = self.add()
        if self.peek() in CMPOPS:
            op = self.take()[0]
            return ("bin", op, left, self.add())
        return left

    def add(self):
        left = self.mul()
        while self.peek() in ("+", "-"):
            op = self.take()[0]
            left = ("bin", op, left, self.mul())
        return left

    def mul(self):
        left = self.unary()
        while self.peek() in ("*", "/", "%"):
            op = self.take()[0]
            left = ("bin", op, left, self.unary())
        return left

    def unary(self):
        if self.peek() == "-":
            self.take()
            return ("neg", self.unary())
        return self.atom()

    def atom(self):
        k, v = self.take()
        if k == "int":
            return ("int", v)
        if k == "ref":
            if self.peek() == ":":
                self.take()
                k2, v2 = self.take()
                if k2 != "ref":
                    raise Err("#SYN")
                return ("range", v, v2)
            return ("ref", v)
        if k == "name":
            if not HAS_FUNCS:
                raise Err("#SYN")
            self.expect("(")
            args = []
            if self.peek() != ")":
                args.append(self.expr())
                while self.peek() == ",":
                    self.take()
                    args.append(self.expr())
            self.expect(")")
            return ("call", v, args)
        if k == "(":
            e = self.expr()
            self.expect(")")
            return e
        raise Err("#SYN")


def validate(n, ok=False):
    k = n[0]
    if k == "range":
        if not ok:
            raise Err("#SYN")
    elif k == "neg":
        validate(n[1])
    elif k == "bin":
        validate(n[2])
        validate(n[3])
    elif k == "call":
        agg = n[1] in AGG
        for a in n[2]:
            validate(a, agg)


def parse_formula(text):
    p = Parser(tokenize(text))
    tree = p.expr()
    if p.i != len(p.t):
        raise Err("#SYN")
    validate(tree)
    return tree


def fdiv(a, b):
    return a // b


def tdiv(a, b):
    q = abs(a) // abs(b)
    return q if (a >= 0) == (b > 0) else -q


def divide(a, b):
    if b == 0:
        raise Err("#DIV")
    if DIVMODE == "exact":
        if a % b != 0:
            raise Err("#DIV")
        return a // b
    return fdiv(a, b) if DIVMODE == "floor" else tdiv(a, b)


def modulo(a, b):
    if b == 0:
        raise Err("#DIV")
    if DIVMODE == "floor":
        return a % b
    return a - b * tdiv(a, b)


def bound(v):
    if abs(v) > LIMIT:
        raise Err("#NUM")
    return v


class Sheet:
    def __init__(self, defs):
        self.defs = defs
        self.memo = {}
        self.busy = set()

    def cell(self, name):
        if name not in self.defs:
            return 0
        if name in self.memo:
            v = self.memo[name]
        elif name in self.busy:
            raise Err("#CYC")
        else:
            self.busy.add(name)
            try:
                v = self.ev(parse_formula(self.defs[name]))
            except Err as e:
                v = e.code
            self.busy.discard(name)
            self.memo[name] = v
        if isinstance(v, str):
            raise Err(v)
        return v

    def ref(self, tok):
        if not valid_cell(tok):
            raise Err("#REF")
        return self.cell(tok)

    def rng(self, a, b):
        if not valid_cell(a) or not valid_cell(b):
            raise Err("#REF")
        c1, c2 = sorted((a[0], b[0]))
        r1, r2 = sorted((int(a[1:]), int(b[1:])))
        vals = []
        for r in range(r1, r2 + 1):
            for c in range(ord(c1), ord(c2) + 1):
                nm = chr(c) + str(r)
                if nm in self.defs:
                    vals.append(self.cell(nm))
        return vals

    def ev(self, n):
        k = n[0]
        if k == "int":
            return bound(int(n[1])) if len(n[1]) <= 9 else bound(LIMIT + 1)
        if k == "ref":
            return self.ref(n[1])
        if k == "neg":
            return -self.ev(n[1])
        if k == "bin":
            a = self.ev(n[2])
            b = self.ev(n[3])
            op = n[1]
            if op == "+":
                return bound(a + b)
            if op == "-":
                return bound(a - b)
            if op == "*":
                return bound(a * b)
            if op == "/":
                return divide(a, b)
            if op == "%":
                return modulo(a, b)
            return int({"=": a == b, "<>": a != b, "<": a < b, "<=": a <= b, ">": a > b, ">=": a >= b}[op])
        return self.call(n[1], n[2])

    def call(self, name, args):
        if name not in CANON:
            raise Err("#NAME")
        f = CANON[name]
        if f in ("SUM", "MIN", "MAX", "AVG", "COUNT"):
            if not args:
                raise Err("#ARG")
            vals = []
            for a in args:
                if a[0] == "range":
                    vals.extend(self.rng(a[1], a[2]))
                else:
                    vals.append(self.ev(a))
            if f == "SUM":
                return bound(sum(vals))
            if f == "COUNT":
                return len(vals)
            if not vals:
                raise Err("#NUM")
            if f == "MIN":
                return min(vals)
            if f == "MAX":
                return max(vals)
            return divide(sum(vals), len(vals))
        if f == "ABS":
            if len(args) != 1:
                raise Err("#ARG")
            return abs(self.ev(args[0]))
        if f == "IF":
            if len(args) != 3:
                raise Err("#ARG")
            return self.ev(args[1]) if self.ev(args[0]) != 0 else self.ev(args[2])
        if f == "CLAMP":
            if len(args) != 3:
                raise Err("#ARG")
            x = self.ev(args[0])
            lo = self.ev(args[1])
            hi = self.ev(args[2])
            if lo > hi:
                raise Err("#ARG")
            return min(max(x, lo), hi)
        if f == "SNAP":
            if len(args) != 2:
                raise Err("#ARG")
            x = self.ev(args[0])
            m = self.ev(args[1])
            if m <= 0:
                raise Err("#ARG")
            return bound((2 * x + m) // (2 * m) * m)
        raise Err("#NAME")


def sheet(source):
    defs = {}
    for no, raw in enumerate(source.split("\n"), 1):
        line = raw.strip(" \t")
        if line == "" or line[0] == "#":
            continue
        i = line.find("=")
        if i < 0:
            return "error: line %d" % no
        name = line[:i].strip(" \t")
        if not valid_cell(name):
            return "error: line %d" % no
        defs[name] = line[i + 1:].strip(" \t")
    sh = Sheet(defs)
    if ORDER == "row":
        names = sorted(defs, key=lambda c: (int(c[1:]), c[0]))
    else:
        names = sorted(defs, key=lambda c: (c[0], int(c[1:])))
    out = []
    for nm in names:
        try:
            v = str(sh.cell(nm))
        except Err as e:
            v = e.code
        out.append("%s = %s" % (nm, v))
    return "\n".join(out)

