solution.sheetcalc.go:
package sheetcalc

import (
	"fmt"
	"sort"
	"strconv"
	"strings"
)

const (
	limit    = 9999999
	divMode  = "floor"
	order    = "row"
	hasFuncs = false
	hasCmp   = false
)

var fn = map[string]string{}

const dig = "0123456789"
const alpha = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ"

type errCode struct{ code string }

func raise(c string) { panic(errCode{c}) }

func canon(name string) (string, bool) {
	for k, v := range fn {
		if v == name {
			return k, true
		}
	}
	return "", false
}

func isAgg(name string) bool {
	if c, ok := canon(name); ok {
		switch c {
		case "SUM", "MIN", "MAX", "AVG", "COUNT":
			return true
		}
	}
	return false
}

func validCell(t string) bool {
	if len(t) < 2 || len(t) > 3 || !strings.ContainsRune("ABCDEFGHIJ", rune(t[0])) || t[1] == '0' {
		return false
	}
	for i := 1; i < len(t); i++ {
		if !strings.ContainsRune(dig, rune(t[i])) {
			return false
		}
	}
	return true
}

type tok struct{ kind, text string }

func tokenize(s string) []tok {
	var out []tok
	i, n := 0, len(s)
	for i < n {
		c := s[i]
		switch {
		case c == ' ' || c == '\t':
			i++
		case strings.IndexByte(dig, c) >= 0:
			j := i
			for j < n && strings.IndexByte(dig, s[j]) >= 0 {
				j++
			}
			out = append(out, tok{"int", s[i:j]})
			i = j
		case strings.IndexByte(alpha, c) >= 0:
			j := i
			for j < n && strings.IndexByte(alpha, s[j]) >= 0 {
				j++
			}
			k := j
			for k < n && strings.IndexByte(dig, s[k]) >= 0 {
				k++
			}
			kind := "name"
			if k > j {
				kind = "ref"
			}
			out = append(out, tok{kind, s[i:k]})
			i = k
		case hasCmp && i+1 < n && (s[i:i+2] == "<>" || s[i:i+2] == "<=" || s[i:i+2] == ">="):
			out = append(out, tok{s[i : i+2], s[i : i+2]})
			i += 2
		case strings.IndexByte("+-*/%(),:", c) >= 0 || (hasCmp && strings.IndexByte("=<>", c) >= 0):
			out = append(out, tok{string(c), string(c)})
			i++
		default:
			raise("#SYN")
		}
	}
	return out
}

type node struct {
	kind string // int ref range neg bin call
	text string
	op   string
	a, b *node
	args []*node
	t2   string
}

type parser struct {
	t []tok
	i int
}

func (p *parser) peek() string {
	if p.i < len(p.t) {
		return p.t[p.i].kind
	}
	return ""
}

func (p *parser) take() tok {
	if p.i >= len(p.t) {
		raise("#SYN")
	}
	t := p.t[p.i]
	p.i++
	return t
}

func (p *parser) expect(k string) {
	if p.peek() != k {
		raise("#SYN")
	}
	p.i++
}

func isCmp(k string) bool {
	return k == "=" || k == "<>" || k == "<" || k == "<=" || k == ">" || k == ">="
}

func (p *parser) expr() *node {
	left := p.add()
	if isCmp(p.peek()) {
		op := p.take().kind
		return &node{kind: "bin", op: op, a: left, b: p.add()}
	}
	return left
}

func (p *parser) add() *node {
	left := p.mul()
	for p.peek() == "+" || p.peek() == "-" {
		op := p.take().kind
		left = &node{kind: "bin", op: op, a: left, b: p.mul()}
	}
	return left
}

func (p *parser) mul() *node {
	left := p.unary()
	for p.peek() == "*" || p.peek() == "/" || p.peek() == "%" {
		op := p.take().kind
		left = &node{kind: "bin", op: op, a: left, b: p.unary()}
	}
	return left
}

func (p *parser) unary() *node {
	if p.peek() == "-" {
		p.take()
		return &node{kind: "neg", a: p.unary()}
	}
	return p.atom()
}

func (p *parser) atom() *node {
	t := p.take()
	switch t.kind {
	case "int":
		return &node{kind: "int", text: t.text}
	case "ref":
		if p.peek() == ":" {
			p.take()
			t2 := p.take()
			if t2.kind != "ref" {
				raise("#SYN")
			}
			return &node{kind: "range", text: t.text, t2: t2.text}
		}
		return &node{kind: "ref", text: t.text}
	case "name":
		if !hasFuncs {
			raise("#SYN")
		}
		p.expect("(")
		var args []*node
		if p.peek() != ")" {
			args = append(args, p.expr())
			for p.peek() == "," {
				p.take()
				args = append(args, p.expr())
			}
		}
		p.expect(")")
		return &node{kind: "call", text: t.text, args: args}
	case "(":
		e := p.expr()
		p.expect(")")
		return e
	}
	raise("#SYN")
	return nil
}

func validate(n *node, ok bool) {
	switch n.kind {
	case "range":
		if !ok {
			raise("#SYN")
		}
	case "neg":
		validate(n.a, false)
	case "bin":
		validate(n.a, false)
		validate(n.b, false)
	case "call":
		agg := isAgg(n.text)
		for _, a := range n.args {
			validate(a, agg)
		}
	}
}

func parseFormula(text string) *node {
	p := &parser{t: tokenize(text)}
	tree := p.expr()
	if p.i != len(p.t) {
		raise("#SYN")
	}
	validate(tree, false)
	return tree
}

func fdiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && ((a < 0) != (b < 0)) {
		q--
	}
	return q
}

func divide(a, b int64) int64 {
	if b == 0 {
		raise("#DIV")
	}
	if divMode == "exact" {
		if a%b != 0 {
			raise("#DIV")
		}
		return a / b
	}
	if divMode == "floor" {
		return fdiv(a, b)
	}
	return a / b
}

func modulo(a, b int64) int64 {
	if b == 0 {
		raise("#DIV")
	}
	if divMode == "floor" {
		return a - b*fdiv(a, b)
	}
	return a - b*(a/b)
}

func bound(v int64) int64 {
	if v > limit || v < -limit {
		raise("#NUM")
	}
	return v
}

type result struct {
	v   int64
	err string
}

type engine struct {
	defs map[string]string
	memo map[string]result
	busy map[string]bool
}

func (e *engine) cell(name string) int64 {
	if _, ok := e.defs[name]; !ok {
		return 0
	}
	r, done := e.memo[name]
	if !done {
		if e.busy[name] {
			raise("#CYC")
		}
		e.busy[name] = true
		r = e.eval(name)
		delete(e.busy, name)
		e.memo[name] = r
	}
	if r.err != "" {
		raise(r.err)
	}
	return r.v
}

func (e *engine) eval(name string) (res result) {
	defer func() {
		if r := recover(); r != nil {
			if ec, ok := r.(errCode); ok {
				res = result{err: ec.code}
				return
			}
			panic(r)
		}
	}()
	return result{v: e.ev(parseFormula(e.defs[name]))}
}

func (e *engine) ref(tok string) int64 {
	if !validCell(tok) {
		raise("#REF")
	}
	return e.cell(tok)
}

func (e *engine) rng(a, b string) []int64 {
	if !validCell(a) || !validCell(b) {
		raise("#REF")
	}
	c1, c2 := a[0], b[0]
	if c1 > c2 {
		c1, c2 = c2, c1
	}
	r1, _ := strconv.Atoi(a[1:])
	r2, _ := strconv.Atoi(b[1:])
	if r1 > r2 {
		r1, r2 = r2, r1
	}
	var vals []int64
	for r := r1; r <= r2; r++ {
		for c := c1; c <= c2; c++ {
			nm := string(rune(c)) + strconv.Itoa(r)
			if _, ok := e.defs[nm]; ok {
				vals = append(vals, e.cell(nm))
			}
		}
	}
	return vals
}

func b2i(b bool) int64 {
	if b {
		return 1
	}
	return 0
}

func sum(v []int64) int64 {
	var s int64
	for _, x := range v {
		s += x
	}
	return s
}

func (e *engine) ev(n *node) int64 {
	switch n.kind {
	case "int":
		if len(n.text) <= 9 {
			v, _ := strconv.ParseInt(n.text, 10, 64)
			return bound(v)
		}
		return bound(limit + 1)
	case "ref":
		return e.ref(n.text)
	case "neg":
		return -e.ev(n.a)
	case "bin":
		a := e.ev(n.a)
		b := e.ev(n.b)
		switch n.op {
		case "+":
			return bound(a + b)
		case "-":
			return bound(a - b)
		case "*":
			return bound(a * b)
		case "/":
			return divide(a, b)
		case "%":
			return modulo(a, b)
		case "=":
			return b2i(a == b)
		case "<>":
			return b2i(a != b)
		case "<":
			return b2i(a < b)
		case "<=":
			return b2i(a <= b)
		case ">":
			return b2i(a > b)
		}
		return b2i(a >= b)
	}
	return e.call(n.text, n.args)
}

func (e *engine) call(name string, args []*node) int64 {
	f, ok := canon(name)
	if !ok {
		raise("#NAME")
	}
	switch f {
	case "SUM", "MIN", "MAX", "AVG", "COUNT":
		if len(args) == 0 {
			raise("#ARG")
		}
		var vals []int64
		for _, a := range args {
			if a.kind == "range" {
				vals = append(vals, e.rng(a.text, a.t2)...)
			} else {
				vals = append(vals, e.ev(a))
			}
		}
		if f == "SUM" {
			return bound(sum(vals))
		}
		if f == "COUNT" {
			return int64(len(vals))
		}
		if len(vals) == 0 {
			raise("#NUM")
		}
		if f == "MIN" || f == "MAX" {
			best := vals[0]
			for _, v := range vals {
				if (f == "MIN" && v < best) || (f == "MAX" && v > best) {
					best = v
				}
			}
			return best
		}
		return divide(sum(vals), int64(len(vals)))
	case "ABS":
		if len(args) != 1 {
			raise("#ARG")
		}
		v := e.ev(args[0])
		if v < 0 {
			v = -v
		}
		return v
	case "IF":
		if len(args) != 3 {
			raise("#ARG")
		}
		if e.ev(args[0]) != 0 {
			return e.ev(args[1])
		}
		return e.ev(args[2])
	case "CLAMP":
		if len(args) != 3 {
			raise("#ARG")
		}
		x := e.ev(args[0])
		lo := e.ev(args[1])
		hi := e.ev(args[2])
		if lo > hi {
			raise("#ARG")
		}
		if x < lo {
			x = lo
		}
		if x > hi {
			x = hi
		}
		return x
	case "SNAP":
		if len(args) != 2 {
			raise("#ARG")
		}
		x := e.ev(args[0])
		m := e.ev(args[1])
		if m <= 0 {
			raise("#ARG")
		}
		return bound(fdiv(2*x+m, 2*m) * m)
	}
	raise("#NAME")
	return 0
}

func trimBlank(s string) string { return strings.Trim(s, " \t") }

// Sheet evaluates a spreadsheet source text.
func Sheet(source string) string {
	defs := map[string]string{}
	for i, raw := range strings.Split(source, "\n") {
		no := i + 1
		line := trimBlank(raw)
		if line == "" || line[0] == '#' {
			continue
		}
		k := strings.IndexByte(line, '=')
		if k < 0 {
			return fmt.Sprintf("error: line %d", no)
		}
		name := trimBlank(line[:k])
		if !validCell(name) {
			return fmt.Sprintf("error: line %d", no)
		}
		defs[name] = trimBlank(line[k+1:])
	}
	e := &engine{defs: defs, memo: map[string]result{}, busy: map[string]bool{}}
	var names []string
	for k := range defs {
		names = append(names, k)
	}
	rowOf := func(c string) int { v, _ := strconv.Atoi(c[1:]); return v }
	sort.Slice(names, func(i, j int) bool {
		a, b := names[i], names[j]
		if order == "row" {
			if rowOf(a) != rowOf(b) {
				return rowOf(a) < rowOf(b)
			}
			return a[0] < b[0]
		}
		if a[0] != b[0] {
			return a[0] < b[0]
		}
		return rowOf(a) < rowOf(b)
	})
	var out []string
	for _, nm := range names {
		var v string
		func() {
			defer func() {
				if r := recover(); r != nil {
					if ec, ok := r.(errCode); ok {
						v = ec.code
						return
					}
					panic(r)
				}
			}()
			v = strconv.FormatInt(e.cell(nm), 10)
		}()
		out = append(out, nm+" = "+v)
	}
	return strings.Join(out, "\n")
}

