public class TestMain {
    public static void main(String[] args) {
        String[][] cases = {
        {"A1 = 12\nA2 = 30\nB1 = A1 + A2 * 2", "A1 = 12\nA2 = 30\nB1 = 72"},
        {"A1 = 4\nA2 = 9\nA3 = 2\nB1 = ADDUP(A1:A3)\nB2 = MAX(A1:A3) - LOWEST(A1:A3)", "A1 = 4\nA2 = 9\nA3 = 2\nB1 = 15\nB2 = 7"},
        {"A1 = 2\nA2 = A1 + B1\nB1 = A2", "A1 = 2\nA2 = #CYC\nB1 = #CYC"},
        };
        int failed = 0;
        for (int i = 0; i < cases.length; i++) {
            String[] c = cases[i];
            String want = c[1];
            String got;
            try {
                got = Sheetcalc.sheet(c[0]);
            } catch (Throwable e) {
                got = "EXCEPTION " + e;
            }
            if (!want.equals(got)) {
                failed++;
                System.out.println("case " + i + " FAILED\n  args: " + String.join(" | ", java.util.Arrays.copyOf(c, 1)) + "\n  got:  " + got + "\n  want: " + want);
            }
        }
        System.out.println((cases.length - failed) + "/" + cases.length + " cases passed");
        if (failed > 0) System.exit(1);
    }
}
